def _load(name):
    shape, chunks = WEIGHTS[name]
    return np.frombuffer(base64.b64decode("".join(chunks)), dtype="<f4").reshape(shape).astype(np.float64)


class Policy:
    """Deterministic actor (mean of the Gaussian policy)."""

    def __init__(self, prefix, n_layers):
        self.mean = _load(prefix + "norm_mean")
        self.std = np.sqrt(_load(prefix + "norm_var") + 1e-5)
        self.layers = [(_load(prefix + "W%d" % j), _load(prefix + "b%d" % j)) for j in range(n_layers)]

    def __call__(self, obs):
        x = np.clip((np.asarray(obs, dtype=np.float64) - self.mean) / self.std, -5.0, 5.0)
        for j, (w, b) in enumerate(self.layers):
            x = w.dot(x) + b
            if j < len(self.layers) - 1:
                x = np.tanh(x)
        return np.clip(x, -1.0, 1.0)


def keeper_script(me, ball):
    """Scripted keeper (team frame): goal line, y = ball y clipped to the goal mouth."""
    ty = clamp(ball[1], -GOAL_HALF + 0.03, GOAL_HALF - 0.03)
    dx, dy = (-HALF_L + 0.07) - me[0], ty - me[1]
    if math.hypot(dx, dy) < 0.03:
        return 0.0, clamp(4.0 * wrap_angle(math.atan2(ball[1] - me[1], ball[0] - me[0]) - me[2]), -W_MAX, W_MAX)
    err = wrap_angle(math.atan2(dy, dx) - me[2])
    return (V_MAX if abs(err) < 0.5 else 0.0), clamp(4.0 * err, -W_MAX, W_MAX)


class Soccer:
    def __init__(self):
        rospy.init_node("soccer")
        team = rospy.get_param("~team", "blue")
        self.first, self.attack = TEAMS[team]
        self.flip = self.attack < 0
        self.ids = [self.first + k for k in range(3)]
        self.opp_ids = [i for i in range(6) if i not in self.ids]
        self.poses = {}  # id -> (x, y, yaw), world frame
        self.vel = {}  # id -> (v, w)
        self.ball = None  # (x, y)
        self.ball_v = (0.0, 0.0)
        self.prev = [(0.0, 0.0)] * 3
        self.score = None
        self.att = Policy("att_", 3)
        self.dfn = Policy("def_", 0) if 0 else None

        self.pubs = {i: rospy.Publisher("/hero_%d/cmd_vel" % i, Twist, queue_size=1) for i in self.ids}
        for i in range(6):
            rospy.Subscriber("/hero_%d/odom" % i, Odometry, self.on_odom, callback_args=i, queue_size=1)
        rospy.Subscriber("/ball/odom", Odometry, self.on_ball, queue_size=1)
        rospy.Subscriber("/game/state", String, self.on_game, queue_size=1)

    def on_odom(self, msg, i):
        self.poses[i] = pose_from_odom(msg)
        self.vel[i] = (msg.twist.twist.linear.x, msg.twist.twist.angular.z)

    def on_ball(self, msg):
        self.ball = (msg.pose.pose.position.x, msg.pose.pose.position.y)
        self.ball_v = (msg.twist.twist.linear.x, msg.twist.twist.linear.y)

    def on_game(self, msg):
        # after a goal everybody goes back to the kickoff: restart the previous actions
        try:
            st = json.loads(msg.data)
            s = (int(st.get("blue", 0)), int(st.get("red", 0)))
        except (ValueError, TypeError, AttributeError):
            return
        if self.score is not None and s != self.score:
            self.prev = [(0.0, 0.0)] * 3
        self.score = s

    def robot(self, i):
        x, y, yaw = self.poses[i]
        v, w = self.vel.get(i, (0.0, 0.0))
        return team_frame_np((x, y, yaw, v, w), self.flip)

    def compute_commands(self, poses, ball):
        """Three (linear_x, angular_z), one per robot of self.ids (keeper first)."""
        mine = [self.robot(i) for i in self.ids]
        theirs = [self.robot(i) for i in self.opp_ids]
        s = -1.0 if self.flip else 1.0
        b = (s * ball[0], s * ball[1], s * self.ball_v[0], s * self.ball_v[1])
        out = []
        for role in range(3):
            if role == 0 and self.dfn is None:
                v, w = keeper_script(mine[0], b)
                self.prev[0] = (v / V_MAX, w / W_MAX)
                out.append((v, w))
                continue
            net = self.dfn if role == 0 else self.att
            a = net(observation_np(mine, theirs, b, role, self.prev[role]))
            self.prev[role] = (float(a[0]), float(a[1]))
            out.append((float(a[0]) * V_MAX, float(a[1]) * W_MAX))
        return out

    def run(self):
        rate = rospy.Rate(CONTROL_HZ)
        while not rospy.is_shutdown():
            if self.ball is None or len(self.poses) < 6:
                rospy.logwarn_throttle(2.0, "waiting for odometry and ball")
            else:
                for i, (v, w) in zip(self.ids, self.compute_commands(self.poses, self.ball)):
                    cmd = Twist()
                    cmd.linear.x, cmd.angular.z = v, w
                    self.pubs[i].publish(cmd)
            rate.sleep()


if __name__ == "__main__":
    Soccer().run()
